#!/usr/bin/env bash
# Veo shots for the vlog version. The phone screen must stay flat chroma green so the UI can be keyed in.
cd "$(dirname "$0")/.."
KEEP="The phone screen stays one uniform flat bright chroma-key green the entire time: no content, no icons, no text, no reflections ever appear on it. Realistic handheld phone video with very subtle natural breathing movement, no zoom, no cuts. Adult woman's hands only, no face. Warm morning light."
H="The woman holds the phone steadily in her left hand, almost perfectly still and facing the camera."
[ -f clips/table.mp4 ] || python3 gen/veo.py clips/table.mp4 frames/table.jpg "$KEEP The smartphone lies on the wooden table. It vibrates briefly three times, buzzing against the wood. Then a woman's hand enters from the bottom right, her index finger taps the screen once near the middle, and the hand leaves the frame. Sound: soft vibration hum, quiet room." ${VEO_MODEL:-veo-3.1-fast-generate-preview} > gen/v-table.log 2>&1 
[ -f clips/scroll.mp4 ] || python3 gen/veo.py clips/scroll.mp4 frames/hand2.jpg "$KEEP $H Her right thumb slowly swipes upward on the screen several times, scrolling through a long chat, pausing briefly between swipes, then rests near the bottom right of the screen." ${VEO_MODEL:-veo-3.1-fast-generate-preview} > gen/v-scroll.log 2>&1 
[ -f clips/type.mp4 ] || python3 gen/veo.py clips/type.mp4 frames/hand2.jpg "$KEEP $H Her right thumb types a message on the lower third of the screen, tapping in quick small natural movements as if on a keyboard, pauses once for a second as if thinking, types again, and finally taps once at the bottom right as if pressing send. Sound: soft phone keyboard taps, quiet kitchen ambience." ${VEO_MODEL:-veo-3.1-fast-generate-preview} > gen/v-type.log 2>&1 
[ -f clips/tap.mp4 ] || python3 gen/veo.py clips/tap.mp4 frames/hand2.jpg "$KEEP $H For three seconds she just reads, the thumb resting. Then her right thumb moves up and taps once in the middle of the screen, and returns to rest near the bottom right corner, and she keeps reading calmly." ${VEO_MODEL:-veo-3.1-fast-generate-preview} > gen/v-tap.log 2>&1 
[ -f clips/read.mp4 ] || python3 gen/veo.py clips/read.mp4 frames/hand2.jpg "$KEEP $H She calmly reads for the whole clip; her right thumb rests below the bottom edge of the screen on the phone's frame and does not touch or cover the screen at all. Only tiny natural breathing movement." ${VEO_MODEL:-veo-3.1-fast-generate-preview} > gen/v-read.log 2>&1
